function QualityControl_HyperSynch(inputs)

% function to run Quality control assessment in a MEA recording, based on the cross-talk between channels
% Analyze hypersynchronicity by calling the functions "HyperSyncTrain" and using the output generated by "ShapeSpikeTimeStamp" and "QualityControl_General"
% (revised October 2026: the result without shuffling is calculated only once per pair; the shuffled spike trains are calculated only once per
%  test cluster j and reused for all its pairs; the "testing" option no longer crashes at the end; by default, only compact results are saved)
% (optional) inputs:    structure to overwrite any variable of the sections INPUTS and PARAMETERS (e.g., inputs.folders, inputs.N_ITERATION); see "override_inputs"
%                       when it is not provided, the values defined in the code are used

if ~parameter_set('active'), clc; end; close all;      % (revised October 2026) no "clc" while "run_pipeline" runs (it would erase its progress messages)
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
system = 3;                 % =1, Ubuntu; =2, Yang's PC; =3, Yang's MacBook; =0, do not modify the MATLAB path (e.g., test harness)
if nargin < 1, inputs = struct(); end                                       % no inputs provided -> use the values defined in the code
if isfield(inputs, 'system'), system = inputs.system; end                   % the system can also be provided as an input
switch system
    case 1      % Anlysis PCP - Ubuntu
        addpath(genpath('/home/cortex/Documents/Yang'));
    case 2      % Yang's PC - GitHub
        addpath(genpath('C:\Users\Yang\OneDrive - Harvard University\Documents\GitHub\MEA-analysis\'));
    case 3      % Yang's MacBook
        addpath(genpath('/Users/sungminyang/Documents/GitHub/CellCircuit'));
end

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%   INPUTS   %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

folders = [
    "/path/to/recording_folder_1";
    "/path/to/recording_folder_2"];

files_data = [
    "recording_name_1";
    "recording_name_2"];

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%   PARAMETERS   %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

        % To set the score
N_ITERATION = 500;                          % number of iterations for the shuffling (default: 500-1000)
N_SPIKES_MINIMUM = 5;                       % minimum number of hypersynchronized spikes to trigger assessment; it will apply to any category (bursting, nonbursting and total) (default: 5)
N_SPIKES_BURST = 8;                         % threshold for the percentage of hypersynchonized spikes within burst, in % (default: 8%)
N_SPIKES_NONBURST = 8;                      % threshold for the percentage of hypersynchonized spikes outside burst, in % (default: 8%)
N_SPIKES_TOTAL = 8;                         % threshold for the percentage of hypersynchonized spikes in all categories, in % (default: 8%)
FACTOR_MINORITY = 2;                        % factor to scale up the threshold when analyzing the minority category (default: 2) 
PERCENTILE_BURST = 95;                      % threshold percentile based on proportion of hypersynchonized spikes within burst, in % (default: 95%)
PERCENTILE_NONBURST = 95;                   % threshold percentile based on proportion of hypersynchonized spikes outside burst, in % (default: 95%)
PERCENTILE_TOTAL = 95;                      % threshold percentile based on proportion of hypersynchonized spikes in all categories, in % (default: 95%)

        % To identify the pairs that are not worth of statistical assessment (because the level of hypersynchronicity is too low) <the higher the threshold, the more permissive>
N_SPIKES_BURST_CUT = 4;                     % threshold for the percentage of hypersynchonized spikes within burst to make the first cut and proceed with the shuffling, in % (default: 4%)
N_SPIKES_NONBURST_CUT = 4;                  % threshold for the percentage of hypersynchonized spikes outside burst to make the first cut and proceed with the shuffling, in % (default: 4%)
N_SPIKES_TOTAL_CUT = 4;                     % threshold for the percentage of hypersynchonized spikes to make the first cut and proceed with the shuffling, in % (default: 4%)

        % Miscellaneous
METHOD_SHUFFLING = 2;                       % method for the spike-train shuffling (=1, uniform; =2, biphasic <burst and non-bust>) 
OPTION_METHOD_BURST = 1;                    % method for the bursting detection (=1, Maximal Interval)
REFRACTORY_PERIOD = 0;                      % refractory period for the shuffling, in msec (default: 0)
K_MSEC_SEC = 1/1000;                        % factor to rescale from msec to sec

option_save_rawQC = 0;                      % =1, also save "rawQC" and "scores" (as before; it can take several GB for ~800 clusters)
                                            % =0, only save the compact results: "hs_master", "hs_final", "hs_percentage" and "red_flag" (revised October 2026)
testing = 0;                                % =1, testing the code; =0, normal use of the code
if testing
   channels = 20:50;                        % select clusters when testing the code
end

apply_parameters('QualityControl_HyperSynch');                              % (revised October 2026) values of the parameter set of "run_pipeline", if any (see "pipeline_parameters")
override_inputs(inputs);                    % overwrite the INPUTS / PARAMETERS above with the ones provided as input (if any)

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%   OUTPUT   %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

% save the following variables in the file sprintf('%s\\%s_QC.mat',folder,file_data):

% rawQC{i,j}:                           cell array that contains the raw results produced by the function "HyperSynTrain" when analyzing the channels i (reference) and j (test)
% score(i,j).number.burst:              score for channels i and j, based on the proportion of hypersynchronized units within bursts (=1, above threshold; =0, below threshold)  
% score(i,j).number.nonburst:           score for channels i and j, based on the proportion of hypersynchronized units outside of bursts (=1, above threshold; =0, below threshold)  
% score(i,j).number.total:              score for channels i and j, based on the proportion of hypersynchronized (=1, above threshold; =0, below threshold)  
% score(i,j).percentile.burst:          score for channels i and j, based on the percentile from hypersynchronicity score of units within bursts (=1, above threshold; =0, below threshold)  
% score(i,j).percentile.nonburst:       score for channels i and j, based on the percentile from hypersynchronicity score of units outside of bursts (=1, above threshold; =0, below threshold)  
% score(i,j).percentile.total:          score for channels i and j, based on the percentile from hypersynchronicity score (=1, above threshold; =0, below threshold)  
% scores{i,j}.final.burst:              final score for hypersynchronicity within bursts (it needs to meet the threshold for both number & percentile)
% scores{i,j}.final.nonburst:           final score for hypersynchronicity ouside bursts (it needs to meet the threshold for both number & percentile)
% scores{i,j}.final.total:              final score for hypersynchronicity for all spikes (it needs to meet the threshold for both number & percentile)
% scores{i,j}.final.master:             final master score for hypersynchronicity for the pair (i,j) (it needs to meet the threshold for non-burst, burst or total)

% red_flag(i,j):                        =2, if the cluster pair (i,j) has super low level of hypersynchronicity (no further assessment)
%                                       =1, if the cluster pair (i,j) has very low level of hypersynchronicity
%                                       =0, the statistical assessment was applied to pair (i,j)

% (revised October 2026) compact results, always saved (only the pairs i<j are filled; "rawQC" and "scores" are only saved if option_save_rawQC=1):
% hs_master(i,j):                       =true, if the pair (i,j) has significant hypersynchronicity (scores{i,j}.final.master = 1); used by "QualityControl_Manual"
% hs_final.burst / nonburst / total(i,j):  =true, if scores{i,j}.final.burst / nonburst / total = 1
% hs_percentage.burst(i,j):             percentage of hypersynchronized spikes within bursts for the pair (i,j)
% hs_percentage.nonburst(i,j):          percentage of hypersynchronized spikes outside bursts for the pair (i,j)
% hs_percentage.total(i,j):             percentage of hypersynchronized spikes for the pair (i,j)

tic                                         % start the timer (to measure the total time)
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%% Check the inputs (folder + files)

n_recordings = numel(files_data);                                               % total number of files to analyze
for k=1:n_recordings                                                            % across all files
    if ~isfile(fullfile(folders(k), sprintf('%s_raw.mat', files_data(k))))       % check the exitence of the file
        error("The file %s (index: %g) can not be found!! ", files_data(k), k)
    end
end

for k=1:n_recordings                                                        % across all recording files
    folder = folders(k);                                                    % path to locate the input file k
    file_data = files_data(k)                                               % file under analysis
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%% Load the data 

file_input = fullfile(folder, sprintf('%s_cleaned.mat',file_data));         % file k to be analyzed
load(file_input, 'spike_plot','discarded_cluster','n_cluster0');            % load the data from file k    
%n_cluster0 = n_cluster;
spikeTimestamp = spike_plot;                                                % It is the initial raw data, before the General Quality Control (since the echo spikes were removed, the original data will be used to assess the hypersynchronicity)
                                                                            % It has only the conditions to be analyzed (not necessarily the full recording)
idx_discarded = find(discarded_cluster>0);                                  % index of clusters to be discarded (identified by "QualityControl_General")
n_discarded = numel(idx_discarded);                                         % total number of clusters to be discarded (identified by "QualityControl_General")
spikeTimestamp(idx_discarded) = [];                                         % eliminate all the clusters with abnormal pattern of activity (identified by "QualityControl_General")
                                                                            % (revised October 2026: all at once; the previous loop also reused "k", the index of the recording file)
if ~testing                                                                 % if it is a normal use (not a test of the algorithm)
    channels = 1:size(spikeTimestamp,2);                                    % load all the clusters
end
fprintf('Total number of originally identified clusters: %g\n', n_cluster0);

if ~isempty(spikeTimestamp)

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%% Analyze the burst structure for all clusters (to save time)

t_step = spikeTimestamp(channels(1)).t_step;                                                        % temporal step, in msec
range = [spikeTimestamp(channels(1)).window(1) spikeTimestamp(channels(1)).window(2)]./K_MSEC_SEC;  % temporal window for analysis, in msec (entire recording)
n_ch = numel(channels);                                                                             % total number of clusters/channels/neurons
fprintf('Total number of filtered clusters to run hypersynchronicity analysis: %g\n', n_ch);

BurstDetected = cell(n_ch,1); BurstFeature = cell(n_ch,1); signals = cell(n_ch,1);                 % initialize the variables for burst structure (revised October 2026: n_ch x 1, it was n_ch x n_ch)
for i=1:n_ch                                                                                        % across all clusters, call "BurstDetection" and "BurstFeatures" for every single cluster and load the results
    BurstDetected{i} = BurstDetection(spikeTimestamp(channels(i)).timeStamp, OPTION_METHOD_BURST);  % Burst detection using spike train of cluster i
    BurstFeature{i} = BurstFeatures(BurstDetected{i});                                              % Burst characterization for cluster i
    signals{i} = [BurstDetected{i}.spikes(:,1) BurstDetected{i}.spikes(:,3)];                       % time stamp of cluster i (column 1) and index of the burst where the spike belongs (column 2; =0 if outside of burst)
end

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%% Analyze hypersynchronicity for all pairs.
% If the proportion of hypersynchronized units is not large enough, or the number of hypersynchronized spikes is low
% do not apply the shuffling method to assess the statistical significance (to save time)

red_flag = zeros(n_ch, n_ch);                                               % to label the pairs depending on the level of hypersynchronicity (in particular, the pairs with low level)
scores = cell(n_ch, n_ch); rawQC = cell(n_ch, n_ch);                        % initialize the variables "scores" and "rawQC" -> output variables to be saved at the end
burst = nan(n_ch, n_ch);  nonburst = nan(n_ch, n_ch);  total = nan(n_ch, n_ch);    % percentage of hypersynchronized spikes for each pair (i,j) -> only used for the plots when testing the code
for i=1:n_ch                                                                % across all clusters
    signal1 = signals{i};                                                   % load data for reference cluster (cluster i will be tested against cluster j)
    for j=i+1:n_ch                                                          % across all clusters (to form the pair with reference cluster i); since there is no directionality for this analysis, only assess each single pair once
        signal2 = signals{j};                                               % load data for test cluster (cluster j will be tested against cluster i)
        QC = HyperSynTrain(signal1,signal2,t_step,range,0,METHOD_SHUFFLING,REFRACTORY_PERIOD,BurstDetected{j},BurstFeature{j});  % analyze the hypersynchronicity for cluster i vs j (no iterations)
        burst(i,j) = QC.burst.nspikes_hs*100;   nonburst(i,j) = QC.nonburst.nspikes_hs*100;   total(i,j) = QC.total.nspikes_hs*100;

        cond=0;                                                             % initialize flag
        if QC.burst.nspikes_hs*100 < N_SPIKES_BURST_CUT || isnan(QC.burst.nspikes_hs)  % proportion of spikes displaying hypersynchronicity within bursts is below threshold (QC.burst.nspikes_hs=NaN when there is no bursting in any of both channels)
            scores{i,j}.number.burst=-1; scores{j,i}.number.burst=-1;       % label the pair as low HS
            cond = cond+1;                                                  % update the flag
        elseif QC.burst.nspikes_total*QC.burst.nspikes_hs < N_SPIKES_MINIMUM    % total number of hypersynchronized spikes within bursts is below threshold
            scores{i,j}.number.burst=-1; scores{j,i}.number.burst=-1;       % label the pair
            cond = cond+1;                                                  % update the flag
        end

        if QC.nonburst.nspikes_hs*100 < N_SPIKES_NONBURST_CUT               % proportion of spikes displaying hypersynchronicity outside of bursts is below threshold
            scores{i,j}.number.nonburst=-1;scores{j,i}.number.nonburst=-1;  % label the pair
            cond = cond+1;                                                  % update the flag
        elseif QC.nonburst.nspikes_total*QC.nonburst.nspikes_hs < N_SPIKES_MINIMUM % total number of hypersynchronized spikes outside of bursts is below threshold
            scores{i,j}.number.nonburst=-1;scores{j,i}.number.nonburst=-1;  % label the pair
            cond = cond+1;                                                  % update the flag
        end

        if QC.total.nspikes_hs*100 < N_SPIKES_TOTAL_CUT                     % proportion of spikes displaying hypersynchronicity is below threshold
            scores{i,j}.number.total=-1; scores{j,i}.number.total=-1;       % label the pair
            cond = cond + 1;                                                % update the flag
         elseif QC.total.nspikes_total*QC.total.nspikes_hs < N_SPIKES_MINIMUM % total number of hypersynchronized spikes is below threshold
            scores{i,j}.number.total=-1; scores{j,i}.number.total=-1;       % label the pair
            cond = cond+1;                                                  % update the flag
        end

        % if all three conditions for super low hypersynchonicity (or low number of replicates) are met
        % in other words, if scores{i,j}.number.burst==-1 && scores{i,j}.number.nonburst==-1 && scores{i,j}.number.total==-1
        if cond==3
           scores{i,j}.percentile.burst = 0;                                % there is no need of statistical assessment
           scores{i,j}.percentile.nonburst = 0;
           scores{i,j}.percentile.total = 0;
           scores{j,i}.percentile.burst = 0;
           scores{j,i}.percentile.nonburst = 0;
           scores{j,i}.percentile.total = 0;
           scores{i,j}.final.master = 0;
           red_flag(i,j)=2;     red_flag(j,i)=2;                            % label the pairs with super low hypersynchronicity
                                                                            % QC for pair (i,j) won't be saved because there is no need
           if testing                                                       % only for testing
              rawQC{i,j}=QC;                                                % save the results of the hypersynchronicity analysis for the pair (i,j), because there are not going to be analyzed any deeper
           end                                                              % do not save the pair (j,i) because is redundant and we need to save space
        else
           rawQC{i,j}=QC;                                                   % keep the result (without shuffling) for the next step (revised October 2026: before, it was calculated again)
        end
    end
end                 % end of the "for" loop across all clusters

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%% Assess the statistical significance of the hypersynchronicity

        % Conservative approach: the point is to identify when the hypersynchronicity is clear and meaningful.
        % When the percentage of HS spikes is not substantial or when the total number of spikes in a category is low (hypersynchronicity can not be appropiately addressed),
        % there is no reason to discard the channel; under this criteria, the quality control and discarding of clusters is based on robust data

out_total=0;   out_burst=0;   out_nonburst=0;    out_final=0;   contador=0; % initialized variables

        % First, identify the pairs that deserve statistical assessment (same criteria as before)
shuffle_pairs = zeros(0,2);                                                 % pairs (i,j) that will be assessed with the shuffled spike trains
for i=1:n_ch                                                                % across all clusters
    for j=i+1:n_ch                                                          % no need to test auto-hypersynchronicity
        scores{i,j}.final.master = 0;
        if red_flag(i,j)<1                                                  % it is NOT a case of super low hypersynchornicity or low number of replicates
            contador = contador + 1;
            QC = rawQC{i,j};                                                % hypersynchronicity for cluster i vs j, without shuffling (calculated in the first step)

            HS_total = QC.total.nspikes_hs*100;                             % percentage of HS, total
            HS_burst = QC.burst.nspikes_hs*100;                             % percentage of HS, burst
            HS_nonburst = QC.nonburst.nspikes_hs*100;                       % percentage of HS, non-burst
            nS_total = QC.total.nspikes_total*QC.total.nspikes_hs;          % HS spikes, total
            nS_burst = QC.burst.nspikes_total*QC.burst.nspikes_hs;          % HS spikes, burst
            nS_nonburst = QC.nonburst.nspikes_total*QC.nonburst.nspikes_hs; % HS spikes, non-burst

            cond_shuff=0;                                                   % initialize flag
            scores{i,j}.number.burst=0;  scores{i,j}.number.nonburst=0;     % initialize variables
            if HS_total > N_SPIKES_TOTAL && nS_total>N_SPIKES_MINIMUM       % the overall level of HS is above threshold
                scores{i,j}.number.total = 1;       cond_shuff = 1;         % label the pair (i,j) for further analysis
            else                                                            % analyze each activity pattern (burst and non-burst) in isolation. Maybe the HS level in one of them is outstanding
                scores{i,j}.number.total = 0;
                if isnan(QC.burst.nspikes_total) || QC.burst.nspikes_total < QC.nonburst.nspikes_total  % the majority of spikes are outside of burst
                    if HS_nonburst>N_SPIKES_NONBURST && nS_nonburst>N_SPIKES_MINIMUM                    % the HS level outside of bursts is above threshold
                       scores{i,j}.number.nonburst = 1;  cond_shuff = 1;                                % label the pair (i,j) for further analysis
                    elseif HS_burst > N_SPIKES_BURST*FACTOR_MINORITY && nS_burst>N_SPIKES_MINIMUM       % the HS level within bursts is above threshold
                        scores{i,j}.number.burst = 1;    cond_shuff = 1;                                % label the pair (i,j) for further analysis
                    end
                else                                                                                    % the majority of spikes are inside of burst
                    if HS_burst>N_SPIKES_BURST && nS_burst>N_SPIKES_MINIMUM                             % the HS level within bursts is above threshold
                       scores{i,j}.number.burst = 1;    cond_shuff = 1;                                 % label the pair (i,j) for further analysis
                    elseif HS_nonburst>N_SPIKES_NONBURST*FACTOR_MINORITY && nS_nonburst>N_SPIKES_MINIMUM% the HS level outside of bursts is above threshold
                       scores{i,j}.number.nonburst = 1; cond_shuff = 1;                                 % label the pair (i,j) for further analysis
                    end
                end
            end

            scores{i,j}.percentile.burst = 0;                               % By default, the initial assumption is that the level hypersynchronicity is not statistically significant
            scores{i,j}.percentile.nonburst = 0;
            scores{i,j}.percentile.total = 0;
            if cond_shuff                                                   % the condition to deserve statistical assessment was met
                shuffle_pairs(end+1,:) = [i j];                             %#ok<AGROW> the shuffling is done below, grouped by cluster j
            else                                                            % there is no need to run statistical assessment
               scores{i,j}.number.burst=0; scores{i,j}.number.nonburst=0; scores{i,j}.number.total = 0;
               red_flag(i,j)=1;                                             % label the pairs with (non-super) low hypersynchronicity
                                                                            % "rawQC{i,j}" already contains the results of the hypersynchronicity analysis for the pair (i,j), because there are not going to be analyzed any deeper
            end
        end
    end
end

        % Second, the statistical assessment, grouped by the test cluster j (revised October 2026)
        % The shuffled spike trains only depend on cluster j (and the random seed is fixed), so they are calculated only once per cluster j,
        % instead of once per pair (i,j): same result, but much faster
test_clusters = unique(shuffle_pairs(:,2));                                 % clusters j with at least one pair that needs statistical assessment
fprintf("Pairs that need statistical assessment: %g (with %g different test clusters) \n", size(shuffle_pairs,1), numel(test_clusters));
for jj=1:numel(test_clusters)                                               % across all test clusters
    j = test_clusters(jj);
    fprintf("Analyzing cluster %g (%g out of %g)... \n", j, jj, numel(test_clusters));
    ShuffleTrain = ShuffleSpikeTrain(signals{j}(:,1), range, t_step, METHOD_SHUFFLING, N_ITERATION, REFRACTORY_PERIOD, BurstDetected{j}, BurstFeature{j});   % shuffle the cluster j "N_ITERATION" times
    ref_clusters = shuffle_pairs(shuffle_pairs(:,2)==j, 1);                 % reference clusters i to be tested against cluster j
    for ii=1:numel(ref_clusters)                                            % across all reference clusters
        i = ref_clusters(ii);
        QC = HyperSynTrain(signals{i},signals{j},t_step,range,N_ITERATION,METHOD_SHUFFLING,REFRACTORY_PERIOD,BurstDetected{j},BurstFeature{j},ShuffleTrain);  % analyze the hypersynchronicity for cluster i vs j
        rawQC{i,j}=QC;                                                      % save the results of the hypersynchronicity analysis for the pair (i,j)
        if QC.burst.percentile > PERCENTILE_BURST                           % percentile/chance for the measured hypersynchronicity within burst is above threshold
            scores{i,j}.percentile.burst = 1;
        end
        if QC.nonburst.percentile > PERCENTILE_NONBURST                     % percentile/chance for the measured hypersynchronicity outside of bursts is above threshold
            scores{i,j}.percentile.nonburst = 1;
        end
        if QC.total.percentile > PERCENTILE_TOTAL                           % percentile/chance for the measured hypersynchronicity is above threshold
            scores{i,j}.percentile.total = 1;
        end
    end
end

        % Third, the final scores for all assessed pairs
for i=1:n_ch                                                                % across all clusters
    for j=i+1:n_ch
        if red_flag(i,j)<2                                                  % it is NOT a case of super low hypersynchornicity (pairs assessed above)
            scores{i,j}.final.burst = scores{i,j}.number.burst * scores{i,j}.percentile.burst;          % it needs to meet the threshold for both number & percentile
            scores{i,j}.final.nonburst = scores{i,j}.number.nonburst * scores{i,j}.percentile.nonburst; % it needs to meet the threshold for both number & percentile
            scores{i,j}.final.total = scores{i,j}.number.total * scores{i,j}.percentile.total;          % it needs to meet the threshold for both number & percentile
            if scores{i,j}.final.burst || scores{i,j}.final.nonburst || scores{i,j}.final.total         % The HS final score is significant for at least one of the categories
                scores{i,j}.final.master = 1;   out_final = out_final + 1;
                if scores{i,j}.final.total                                                              % the HS final score is significant for the overall activity
                    out_total = out_total + 1;
                elseif scores{i,j}.final.burst                                                          % the HS final score is significant for the spikes within burst
                    out_burst = out_burst + 1;
                elseif scores{i,j}.final.nonburst                                                       % the HS final score is significant for the spikes outside burst
                    out_nonburst = out_nonburst + 1;
                end
            end
        end
    end
end
        % Compact results (revised October 2026): the same information used by "QualityControl_Manual", in a few small matrices
hs_master = false(n_ch);   hs_final = struct('burst', false(n_ch), 'nonburst', false(n_ch), 'total', false(n_ch));
for i=1:n_ch
    for j=i+1:n_ch
        if red_flag(i,j)<2                                                  % only the assessed pairs can be significant
            hs_master(i,j) = scores{i,j}.final.master == 1;
            hs_final.burst(i,j) = scores{i,j}.final.burst == 1;
            hs_final.nonburst(i,j) = scores{i,j}.final.nonburst == 1;
            hs_final.total(i,j) = scores{i,j}.final.total == 1;
        end
    end
end
hs_percentage = struct('burst', single(burst), 'nonburst', single(nonburst), 'total', single(total));    % percentage of hypersynchronized spikes for each pair (single precision, to save space)

toc                                                                         % turn the timer off
disp('Statistical analysis')
fprintf('Total number of non-super-low HS: %g\n', contador);
fprintf('Total number of statistically signicant HS pairs: %g\n', out_final)
fprintf('... for total HS: %g\n', out_total);
fprintf('... for burst HS: %g\n', out_burst);
fprintf('... for non-burst HS: %g\n', out_nonburst);

else
    rawQC = [];
    scores = [];
    red_flag = [];
    hs_master = [];     hs_final = [];      hs_percentage = [];
    fprintf('\n \n There is NO available units to run the test \n \n');
end
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%% Save the results

file_output = fullfile(folder, sprintf('%s_QC.mat',file_data));
if option_save_rawQC                                                        % all the results (as before; large file)
    save(file_output,'rawQC', 'scores','red_flag','hs_master','hs_final','hs_percentage', '-v7.3');
else                                                                        % only the compact results (revised October 2026)
    save(file_output,'red_flag','hs_master','hs_final','hs_percentage');
end

end         % close the "for" loop across the different files
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%% Plot the result

if testing                    % when testing the code (revised October 2026: "burst", "nonburst" and "total" were not defined, and the code crashed here)
    figure(1)
    histogram(burst);    title('Burst');

    figure(2)
    histogram(nonburst);    title('Non-Burst');

    figure(3)
    histogram(total);    title('Total');

    figure(4)
    plot(burst, nonburst,'ko');    xlabel('Burst');    ylabel('non-Burst');
end
end
